CREATE TABLE proc_products(id BIGINT PRIMARY KEY,sku TEXT,name TEXT,description TEXT,category_id BIGINT,unit TEXT,manufacturer TEXT,model TEXT,parameters JSONB,attributes JSONB,reorder_point DOUBLE PRECISION,target_stock DOUBLE PRECISION,active BOOLEAN,updated_at TIMESTAMPTZ);
