CREATE TABLE proc_offers(id BIGINT PRIMARY KEY,product_id BIGINT,supplier_id BIGINT,supplier_sku TEXT,price_cents BIGINT,currency TEXT,minimum_quantity DOUBLE PRECISION,pack_size DOUBLE PRECISION,lead_days INT,purchase_url TEXT,valid_until TIMESTAMPTZ,last_checked_at TIMESTAMPTZ,active BOOLEAN);
