CREATE TABLE proc_requisitions(id BIGINT PRIMARY KEY,number TEXT,title TEXT,status TEXT,requester_id BIGINT,requester_name TEXT,cost_center TEXT,justification TEXT,needed_by TIMESTAMPTZ,estimated_total_cents BIGINT,approved_by_name TEXT,decision_note TEXT,submitted_at TIMESTAMPTZ,decided_at TIMESTAMPTZ,created_at TIMESTAMPTZ,updated_at TIMESTAMPTZ,is_archived BOOLEAN);
