CREATE TABLE proc_purchase_orders(id BIGINT PRIMARY KEY,number TEXT,status TEXT,supplier_id BIGINT,order_date TIMESTAMPTZ,expected_delivery TIMESTAMPTZ,currency TEXT,created_at TIMESTAMPTZ,updated_at TIMESTAMPTZ);
CREATE TABLE proc_purchase_order_lines(id BIGINT PRIMARY KEY,purchase_order_id BIGINT,product_id BIGINT,quantity DOUBLE PRECISION,received_quantity DOUBLE PRECISION,unit_price_cents BIGINT);
