CREATE TABLE jobs(jobid BIGINT PRIMARY KEY,job_code TEXT,description TEXT,statusid BIGINT,deleted_at TIMESTAMPTZ,startdate TIMESTAMPTZ,enddate TIMESTAMPTZ,updated_at TIMESTAMPTZ);
CREATE TABLE job_product_requirements(id BIGINT PRIMARY KEY,job_id BIGINT,product_id BIGINT,quantity DOUBLE PRECISION,deleted_at TIMESTAMPTZ);
CREATE TABLE status(statusid BIGINT PRIMARY KEY,status TEXT);
CREATE TABLE defect_reports(defect_id BIGINT PRIMARY KEY,device_id TEXT,severity TEXT,status TEXT,updated_at TIMESTAMPTZ);
CREATE TABLE maintenance_orders(order_id BIGINT PRIMARY KEY,title TEXT,priority TEXT,status TEXT,due_at TIMESTAMPTZ,updated_at TIMESTAMPTZ);
CREATE TABLE warehouse_tasks(task_id BIGINT PRIMARY KEY,status TEXT);
CREATE TABLE job_history(history_id BIGINT PRIMARY KEY,job_id BIGINT,change_type TEXT,field_name TEXT,changed_at TIMESTAMPTZ);
CREATE TABLE device_movements(movement_id BIGINT PRIMARY KEY,device_id TEXT,movement_type TEXT,created_at TIMESTAMPTZ);
CREATE TABLE planner_tasks(id UUID PRIMARY KEY,plan_id UUID,bucket_id UUID,title TEXT,rich_text_notes TEXT,priority TEXT,progress INT,completed_at TIMESTAMPTZ,due_date TIMESTAMPTZ,updated_at TIMESTAMPTZ);
