CREATE TABLE categories(categoryid BIGINT PRIMARY KEY,name TEXT);
CREATE TABLE manufacturer(manufacturerid BIGINT PRIMARY KEY,name TEXT);
ALTER TABLE products ADD categoryid BIGINT,ADD manufacturerid BIGINT,ADD description TEXT,ADD model_number TEXT,ADD updated_at TIMESTAMPTZ;
ALTER TABLE proc_suppliers ADD code TEXT,ADD active BOOLEAN,ADD updated_at TIMESTAMPTZ;
CREATE TABLE venues(id BIGINT PRIMARY KEY,name TEXT,city TEXT,zip TEXT,updated_at TIMESTAMPTZ);
CREATE TABLE cases(caseid BIGINT PRIMARY KEY,name TEXT,barcode TEXT,workflow_status TEXT,zone_id BIGINT,updated_at TIMESTAMPTZ);
CREATE TABLE storage_zones(zone_id BIGINT PRIMARY KEY,name TEXT);
